53	 * and messages specific to this application's context.
54	 */
55	class Exception : public std::exception
56	{
57	public:
58	    /**
59	     * @brief Constructs an exception with a status code and a formatted message.
60	     *
61	     * @param code The error status code.
62	     * @param fmt The format string for the error message.
63	     * @param args The format arguments.
64	     */
65	    explicit Exception(Status code)
66	        : Exception(code, "%s", "")
67	    {
68	    }
69	
70	    explicit Exception(Status code, const char *msg)
71	        : Exception(code, "%s", msg != nullptr ? msg : "")
72	    {
73	    }
74	
75	    template<size_t N, class... Args>
76	    explicit Exception(Status code, const char (&fmt)[N], Args &&...args)
77	        : m_code(code)
78	    {
79	        doSetMessage(fmt, std::forward<Args>(args)...);
80	        nvcvSetThreadStatus(static_cast<NVCVStatus>(code), "%s", m_msg);
81	    }
82	
83	    /**
84	     * @brief Retrieves the status code of the exception.
85	     *
86	     * @return The error status code.
87	     */
88	    Status code() const
89	    {
90	        return m_code;
91	    }
92	
93	    /**
94	     * @brief Retrieves the message of the exception.
95	     *
96	     * @return The error message.
97	     */
98	    const char *msg() const
99	    {
100	        return m_msg;
101	    }
102	
103	    /**
104	     * @brief Retrieves the exception message.
105	     *
106	     * This function overrides the standard exception's what() method.
107	     *
108	     * @return The error message.
109	     */
110	    const char *what() const noexcept override
111	    {
112	        return m_msgBuffer.data();
113	    }
114	
115	private:
116	    Status      m_code;
117	    const char *m_msg;
118	
119	    // 64: maximum size of string representation of a status enum
120	    // 2: ': '
121	    std::array<char, NVCV_MAX_STATUS_MESSAGE_LENGTH + 64 + 2> m_msgBuffer;
122	
123	    friend void detail::ThrowException(NVCVStatus status);
124	
125	    struct InternalCtorTag
126	    {
127	    };
128	
129	    Exception(InternalCtorTag, Status code)
130	        : Exception(InternalCtorTag{}, code, "%s", "")
131	    {
132	    }
133	
134	    Exception(InternalCtorTag, Status code, const char *msg)
135	        : Exception(InternalCtorTag{}, code, "%s", msg != nullptr ? msg : "")
136	    {
137	    }
138	
139	    // Constructor that doesn't set the C thread status. Used when converting C statuses to C++.
140	    template<size_t N, class... Args>
141	    Exception(InternalCtorTag, Status code, const char (&fmt)[N], Args &&...args)
142	        : m_code(code)
143	    {
144	        doSetMessage(fmt, std::forward<Args>(args)...);
145	    }
146	
147	    template<size_t N, class... Args>
148	    void doSetMessage(const char (&fmt)[N], Args &&...args)
149	    {
150	        auto buflen = static_cast<int>(m_msgBuffer.size());
151	
152	        // no truncation?
153	        detail::FormatTo(m_msgBuffer.data(), m_msgBuffer.size(), "%s: ", GetName(m_code));
154	
155	        int nwritten = static_cast<int>(std::char_traits<char>::length(m_msgBuffer.data()));
156	        if (nwritten < buflen - 1)
157	        {
158	            buflen -= nwritten;
159	            m_msg = m_msgBuffer.data() + nwritten;
160	            detail::FormatTo(m_msgBuffer.data() + nwritten, static_cast<std::size_t>(buflen), fmt,
161	                             std::forward<Args>(args)...);
162	        }
163	
164	        m_msgBuffer.back() = '\0';
165	    }
166	};
