168	/**
169	 * @brief Sets the thread's error status based on a captured exception.
170	 *
171	 * This function tries to rethrow the given exception and based on its type, it sets the appropriate
172	 * error status for the current thread using the `nvcvSetThreadStatus` function.
173	 *
174	 * @param e The captured exception to be rethrown and processed.
175	 */
176	inline void SetThreadError(std::exception_ptr e)
177	{
178	    try
179	    {
180	        if (e)
181	        {
182	            rethrow_exception(e);
183	        }
184	        else
185	        {
186	            nvcvSetThreadStatus(NVCV_SUCCESS, nullptr);
187	        }
188	    }
189	    catch (const Exception &e)
190	    {
191	        nvcvSetThreadStatus(static_cast<NVCVStatus>(e.code()), "%s", e.msg());
192	    }
193	    catch (const std::invalid_argument &e)
194	    {
195	        nvcvSetThreadStatus(NVCV_ERROR_INVALID_ARGUMENT, "%s", e.what());
196	    }
197	    catch (const std::domain_error &e)
198	    {
199	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "%s", e.what());
200	    }
201	    catch (const std::length_error &e)
202	    {
203	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "%s", e.what());
204	    }
205	    catch (const std::out_of_range &e)
206	    {
207	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "%s", e.what());
208	    }
209	    catch (const std::bad_alloc &)
210	    {
211	        nvcvSetThreadStatus(NVCV_ERROR_OUT_OF_MEMORY, "Not enough space for resource allocation");
212	    }
213	    catch (const std::range_error &e)
214	    {
215	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "%s", e.what());
216	    }
217	    catch (const std::overflow_error &e)
218	    {
219	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "%s", e.what());
220	    }
221	    catch (const std::underflow_error &e)
222	    {
223	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "%s", e.what());
224	    }
225	    catch (...) // NOSONAR: API boundary converts any non-standard exception to NVCV status.
226	    {
227	        nvcvSetThreadStatus(NVCV_ERROR_INTERNAL, "Unexpected error");
228	    }
229	}
